@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (isLoading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="stats-card bg-primary bg-opacity-10 border-primary">
                <div class="stats-value">@allTasks.Count</div>
                <div class="stats-label">Total Tasks</div>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-secondary bg-opacity-10 border-secondary">
                <div class="stats-value">@GetTasksForColumn("To Do").Count</div>
                <div class="stats-label">To Do</div>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-info bg-opacity-10 border-info">
                <div class="stats-value">@GetTasksForColumn("In Progress").Count</div>
                <div class="stats-label">In Progress</div>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-success bg-opacity-10 border-success">
                <div class="stats-value">@GetTasksForColumn("Done").Count</div>
                <div class="stats-label">Done</div>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-danger bg-opacity-10 border-danger">
                <div class="stats-value">@OverdueCount</div>
                <div class="stats-label">Overdue</div>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text"
               class="form-control"
               placeholder="Search tasks by title..."
               @bind="searchQuery"
               @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @foreach (var column in columns)
        {
            var columnTasks = GetFilteredTasksForColumn(column);
            var colIndex = Array.IndexOf(columns, column);

            <div class="col-md-4">
                <div class="kanban-column">
                    <div class="kanban-column-header">
                        <span>@column</span>
                        <span class="badge bg-secondary rounded-pill">@columnTasks.Count</span>
                    </div>

                    <div class="kanban-cards">
                        @foreach (var task in columnTasks)
                        {
                            <div class="kanban-card">
                                <div class="d-flex justify-content-between align-items-start mb-1">
                                    <strong class="card-title-text">@task.Title</strong>
                                    <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
                                </div>
                                <div class="text-muted small mb-2">@task.Assignee</div>
                                <div class="d-flex justify-content-between align-items-center">
                                    <span class="text-muted small">@task.DueDate.ToString("MMM dd")</span>
                                    <div class="btn-group btn-group-sm">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@movingTaskIds.Contains(task.Id)"
                                                    @onclick="() => MoveTaskAsync(task.Id, columns[colIndex - 1])">
                                                ◀ Move Left
                                            </button>
                                        }
                                        @if (colIndex < columns.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@movingTaskIds.Contains(task.Id)"
                                                    @onclick="() => MoveTaskAsync(task.Id, columns[colIndex + 1])">
                                                Move Right ▶
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }
                    </div>

                    @if (addingToColumn == column)
                    {
                        <div class="kanban-card new-task-form">
                            <div class="mb-2">
                                <input type="text" class="form-control form-control-sm" placeholder="Title"
                                       @bind="newTitle" />
                            </div>
                            <div class="mb-2">
                                <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                                       @bind="newAssignee" />
                            </div>
                            <div class="mb-2">
                                <select class="form-select form-select-sm" @bind="newPriority">
                                    <option value="High">High</option>
                                    <option value="Medium">Medium</option>
                                    <option value="Low">Low</option>
                                </select>
                            </div>
                            <div class="mb-2">
                                <input type="date" class="form-control form-control-sm"
                                       @bind="newDueDate" />
                            </div>
                            @if (saveError is not null)
                            {
                                <div class="text-danger small mb-2">@saveError</div>
                            }
                            <div class="d-flex gap-2">
                                <button class="btn btn-primary btn-sm" disabled="@isSaving" @onclick="SaveNewTaskAsync">
                                    @(isSaving ? "Saving..." : "Save")
                                </button>
                                <button class="btn btn-outline-secondary btn-sm" disabled="@isSaving" @onclick="CancelAdd">
                                    Cancel
                                </button>
                            </div>
                        </div>
                    }
                    else
                    {
                        <button class="btn btn-outline-primary btn-sm w-100 mt-2" @onclick="() => StartAdd(column)">
                            + Add Task
                        </button>
                    }
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchQuery = string.Empty;

    // Add-task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);
    private bool isSaving;
    private string? saveError;

    // Track tasks currently being moved to disable their buttons
    private readonly HashSet<int> movingTaskIds = new();

    private int OverdueCount => allTasks.Count(t => t.DueDate.Date < DateTime.Today && t.Status != "Done");

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksForColumn(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksForColumn(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(searchQuery))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase));
        }

        return tasks.ToList();
    }

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        movingTaskIds.Add(taskId);

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                allTasks[idx] = allTasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            movingTaskIds.Remove(taskId);
        }
    }

    private void StartAdd(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
        saveError = null;
    }

    private void CancelAdd()
    {
        addingToColumn = null;
        saveError = null;
    }

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(newTitle))
        {
            saveError = "Title is required.";
            return;
        }

        isSaving = true;
        saveError = null;

        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle.Trim(), newAssignee.Trim(), newPriority, newDueDate);

            // If the task was created with a different status than the target column, move it
            if (created.Status != addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, addingToColumn!);
                created = created with { Status = addingToColumn! };
            }

            allTasks.Add(created);
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            saveError = ex.Message;
        }
        finally
        {
            isSaving = false;
        }
    }
}

.stats-card {
    border: 1px solid;
    border-radius: 0.5rem;
    padding: 0.75rem 1rem;
    text-align: center;
}

.stats-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stats-label {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    opacity: 0.8;
}

.kanban-column {
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 1rem;
    min-height: 400px;
    display: flex;
    flex-direction: column;
}

.kanban-column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 600;
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
    padding-bottom: 0.5rem;
    border-bottom: 2px solid #dee2e6;
}

.kanban-cards {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.kanban-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.kanban-card:hover {
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
}

.card-title-text {
    word-break: break-word;
    flex: 1;
    margin-right: 0.5rem;
}

.new-task-form {
    border: 2px dashed #0d6efd;
    background: #f0f4ff;
}

::deep .priority-high {
    background-color: #dc3545;
    color: #fff;
}

::deep .priority-medium {
    background-color: #ffc107;
    color: #212529;
}

::deep .priority-low {
    background-color: #198754;
    color: #fff;
}

