    {
        addingToColumn = null;
        saveError = null;
    }

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(newTitle))
        {
            saveError = "Title is required.";
            return;
        }

        isSaving = true;
        saveError = null;

        try
        {
