toolArgs.file_text:
.stats-card {
    border: 1px solid;
    border-radius: 0.5rem;
    padding: 0.75rem 1rem;
    text-align: center;
}

.stats-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stats-label {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    opacity: 0.8;
}

.kanban-column {
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 1rem;
    min-height: 400px;
    display: flex;
    flex-direction: column;
}

.kanban-column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 600;
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
    padding-bottom: 0.5rem;
    border-bottom: 2px solid #dee2e6;
}

.kanban-cards {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.kanban-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.kanban-card:hover {
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
}

.card-title-text {
    word-break: break-word;
    flex: 1;
    margin-right: 0.5rem;
}

.new-task-form {
    border: 2px dashed #0d6efd;
    background: #f0f4ff;
}

::deep .priority-high {
    background-color: #dc3545;
    color: #fff;
}

::deep .priority-medium {
    background-color: #ffc107;
    color: #212529;
}

::deep .priority-low {
    background-color: #198754;
    color: #fff;
}

